1	// `andesim run --mode fast|cycle|hybrid [engine selection] ELF [-- engine args]`.
2	//
3	// The top selection axis. F7/F8 land the two standalone models, `fast` (QEMU)
4	// and `cycle` (a cycle-accurate engine, from reset): each resolves its
5	// engine, then hands off to transparent passthrough -- the ELF plus everything
6	// after `--` becomes the engine's own command line, run with inherited stdio,
7	// no timeout, and the exit code propagated, so a gdbstub / monitor /
8	// semihosting console all behave as if the engine were invoked directly.
9	// `hybrid` (F9) orchestrates a QEMU1 -> vsim handoff via run_plan and prints the
10	// window-cycle figure (the vsim mcycle delta).
11	#include <algorithm>
12	#include <chrono>
13	#include <cstdint>
14	#include <cstdio>
15	#include <cstdlib>
16	#include <filesystem>
17	#include <optional>
18	#include <string>
19	#include <thread>
20	#include <vector>
21	
22	#include "argv.hpp"
23	#include "cli.hpp"
24	#include "elf_syms.hpp"
25	#include "engine_descriptor.hpp"
26	#include "engine_registry.hpp"
27	#include "hybrid.hpp"
28	#include "hybrid/state_abi.h"  // HYBRID_V_SCRATCH_BYTES (L26/F3 overlap check)
29	#include "models.hpp"
30	#include "plan.hpp"
31	#include "process.hpp"
32	#include "repo_root.hpp"
33	#include "run_passthrough.hpp"
34	#include "run_plan.hpp"
35	#include "shm.hpp"
36	#include "state.hpp"
37	#include "state_diff.hpp"
38	
39	namespace fs = std::filesystem;
40	
41	namespace andes_sim {
42	namespace {
43	
44	// Resolve `path` to an absolute path. Returns the resolved string on success;
45	// on failure prints an error tagged with `ctx` and returns "".
46	std::string abs_elf(const std::string& path, const std::string& ctx) {
47	  std::error_code ec;
48	  std::string abs = fs::absolute(path, ec).string();
49	  if (ec) {
50	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
51	                 ctx.c_str(), path.c_str());
52	    return "";
53	  }
54	  return abs;
55	}
56	
57	// Validate the lone-ELF positional shape the standalone models require: print
58	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
59	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
60	// spawns a --describe subprocess per Verilator build). `model` labels the error.
61	int check_one_elf(const Cli& cli, const char* model) {
62	  if (cli.positional.empty()) {
63	    std::fprintf(stderr,
64	                 "andesim run --mode %s: missing ELF (the workload to run; "
65	                 "e.g. a tests/fixtures/<name>.elf)\n",
66	                 model);
67	    return 2;
68	  }
69	  if (cli.positional.size() > 1) {
70	    std::fprintf(stderr,
71	                 "andesim run --mode %s: unexpected argument '%s' "
72	                 "(engine args go after --)\n",
73	                 model, cli.positional[1].c_str());
74	    return 2;
75	  }
76	  return 0;
77	}
78	
79	// The standalone-passthrough spine shared by `fast` and `cycle`: both take a
80	// single ELF, then exec the resolved engine standalone with `extra` (model
81	// flags the framework forwards, e.g. fast's -m) followed by the post-`--`
82	// args verbatim (inherit stdio, no timeout, propagate exit code). The only
83	// per-model differences -- which engine, and how it is selected -- are resolved
84	// by the caller; `model` here only labels the positional diagnostics.
85	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
86	                   const char* model,
87	                   const std::vector<std::string>& extra = {}) {
88	  if (int rc = check_one_elf(cli, model)) return rc;
89	  // QEMU's -bios flag searches its data directory for relative paths rather
90	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
91	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
92	  if (elf.empty()) return 2;
93	  std::vector<std::string> args = extra;
94	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
95	  std::string err;
96	  int rc = run_passthrough(eng, "standalone", elf, args, err);
97	  if (!err.empty()) std::fprintf(stderr, "andesim run: %s\n", err.c_str());
98	  return rc;
99	}
100	
101	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
102	// only the built-in qemu descriptor, so it resolves that directly rather than
103	// discover_engines(), which would spawn a --describe subprocess per Verilator
104	// build only to discard them all here.
105	int run_fast(const Cli& cli) {
106	  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
107	  if (!cli.engine.empty() && cli.engine != "qemu64" && cli.engine != "qemu32") {
108	    std::fprintf(stderr,
109	                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
110	                 "got '%s'\n",
111	                 cli.engine.c_str());
112	    return 2;
113	  }
114	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
115	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
116	  std::string err;
117	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
118	  if (!err.empty()) {
119	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
120	    return 2;
121	  }
122	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
123	  if (cli.gdb) {
124	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
125	    extra.push_back("-gdb");
126	    extra.push_back("tcp::" + port);
127	    extra.push_back("-S");
128	  }
129	  return run_standalone(cli, builtin_qemu_arch(cli.engine == "qemu32" ? 32 : 64),
130	                        "fast", extra);
131	}
132	
133	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
134	// its --jtag-port only after it has reset and halted the hart, so the debugger we
135	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
136	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
137	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
138	// single debugger slot). Returns false on timeout.
139	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
140	  constexpr int kPollMs = 50;
141	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
142	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
143	      char line[512];
144	      while (std::fgets(line, sizeof line, f)) {
145	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
146	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
147	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
148	        unsigned lport = 0, st = 0;
149	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
150	            && st == 0x0A && lport == port) {
151	          std::fclose(f);
152	          return true;
153	        }
154	      }
155	      std::fclose(f);
156	    }
157	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
158	  }
159	  return false;
160	}
161	
162	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
163	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
164	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
165	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
166	  const char* iceman = std::getenv("ICEMAN");
167	  if (!iceman || !*iceman) {
168	    std::fprintf(stderr,
169	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
170	                 "(export ICEMAN=<path to ICEman binary>)\n");
171	    return 2;
172	  }
173	  // Build vsim argv from the standalone template, appending user passthrough
174	  // and the JTAG port flag.
175	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
176	  if (elf.empty()) return 2;
177	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
178	  std::vector<std::string> vsim_pass = cli.passthrough;
179	  vsim_pass.push_back("--jtag-port");
180	  vsim_pass.push_back(jtag_port);
181	  std::string err;
182	  const std::vector<std::string> vsim_argv =
183	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
184	  if (!err.empty()) {
185	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
186	    return 2;
187	  }
188	  std::fprintf(stderr,
189	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
190	               jtag_port.c_str());
191	  if (fork_background(vsim_argv) < 0) {
192	    std::fprintf(stderr,
193	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
194	    return 1;
195	  }
196	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
197	  // Wait for the port to be LISTENing before launching the debugger (it does not
198	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
199	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
200	  // but launch anyway if it never appears.
201	  if (const int pnum = std::atoi(jtag_port.c_str());
202	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
203	    std::fprintf(stderr,
204	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
205	                 "after 20s; launching the debugger anyway\n",
206	                 jtag_port.c_str());
207	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
208	  // localhost, port 9104) instead of its default real-hardware adapter; without
209	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
210	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
211	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
212	}
213	
214	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
215	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
216	// engine's own output. Unlike fast, this must discover the Verilator build(s)
217	// to resolve the engine (explicit --engine, else the sole one).
218	int run_accurate(const Cli& cli) {
219	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
220	  // --describe subprocess per Verilator build only to fail on the argument.
221	  if (int rc = check_one_elf(cli, "cycle")) return rc;
222	  // --mem-size is validated but has nothing to size: the cycle engine always
223	  // models its full DRAM window. Say so instead of silently ignoring it.
224	  if (!cli.mem_size.empty()) {
225	    std::string se;
226	    if (parse_size(cli.mem_size, se); !se.empty()) {
227	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
228	                   se.c_str());
229	      return 2;
230	    }
231	    std::fprintf(stderr,
232	                 "[andesim] --mem-size: the cycle engine models its full "
233	                 "DRAM window; nothing to size\n");
234	  }
235	  Discovery disc = discover_engines();
236	  std::string err;
237	  const EngineDescriptor* eng =
238	      resolve_accurate_engine(disc.engines, cli.engine, err);
239	  if (!eng) {
240	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
241	    // Surface why an expected engine may be absent (failed --describe, etc.).
242	    for (const std::string& w : disc.warnings)
243	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
244	    return 2;
245	  }
246	  if (cli.gdb) return run_cycle_gdb(cli, *eng);
247	  return run_standalone(cli, *eng, "cycle");
248	}
249	
250	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
251	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle
252	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
253	// driver's tests/e2e.sh delegation with a single window-cycle line.
254	int run_hybrid(const Cli& cli) {
255	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
256	  auto fail = [](const std::string& msg) {
257	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
258	    return 2;
259	  };
260	
261	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
262	
263	  // Resolve to an absolute, existing path: a clean error beats a downstream
264	  // spawn failure, and pc-trigger resolution reads the ELF's .symtab.
265	  std::error_code ec;
266	  const fs::path elf = fs::absolute(cli.positional[0], ec);
267	  if (ec || !fs::is_regular_file(elf, ec))
268	    return fail("ELF not found: " + cli.positional[0]);
269	  const std::string elf_path = elf.string();
270	
271	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
272	  // mistake fails fast without spawning a --describe per Verilator build.
273	  std::string err;
274	  const Trigger trig = hybrid_trigger(cli, elf_path, err);
275	  if (!err.empty()) return fail(err);
276	
277	  // hybrid_trigger has already guaranteed trig.kind is marker|pc (the only
278	  // hybrid triggers; unknown returned an error above) -- exactly the entry
279	  // boundary --verify needs the oracle to arm on.
280	  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
281	  if (!err.empty()) return fail(err);
282	
283	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
284	  if (!cli.mem_size.empty()) {
285	    std::string se;
286	    mem = parse_size(cli.mem_size, se);
287	    if (!se.empty()) return fail("--mem-size: " + se);
288	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
289	    // guest RAM here. The physical mmap reserves one V-scratch page above the
290	    // program's RAM (L26/F2), so the usable --mem-size is 2 GiB minus that
291	    // page. Failing now beats allocating a huge mmap file first and letting
292	    // QEMU die late.
293	    if (mem > max_program_mem_bytes())
294	      return fail("--mem-size " + cli.mem_size +
295	                  " exceeds the AE350 DRAM window (2G minus the V-scratch "
296	                  "reservation)");
297	  }
298	
299	  // L26/F3: refuse a run whose static image would extend into the reserved
300	  // V-transport scratch page. Scheme D parks the scratch in the TOP page of the
301	  // physical mmap; a PT_LOAD segment reaching there means the ELF was linked for
302	  // more RAM than --mem-size grants, and QEMU would load it straight onto the
303	  // scratch -> silent corruption. Derive the page's start from
304	  // physical_mmap_bytes (the same sizing the mmap uses) rather than a bare
305	  // `mem`, so the threshold tracks the reservation shape instead of relying on
306	  // the +page/-page adjustments cancelling. ram_base is the fixed andes_ae350
307	  // DRAM base (0; see L10). Skipped when the ELF cannot be read -- downstream
308	  // reports it.
309	  {
310	    std::string e;
311	    const uint64_t top = elf_load_top(elf_path, e);
312	    const uint64_t scratch_gpa =
313	        static_cast<uint64_t>(physical_mmap_bytes(mem)) - HYBRID_V_SCRATCH_BYTES;
314	    if (e.empty() && top > scratch_gpa) {
315	      char msg[256];
316	      std::snprintf(msg, sizeof(msg),
317	                    "ELF static image ends at 0x%llx, overlapping the reserved "
318	                    "V-transport scratch page at 0x%llx (ram_base + --mem-size)"
319	                    "; raise --mem-size or shrink the image",
320	                    static_cast<unsigned long long>(top),
321	                    static_cast<unsigned long long>(scratch_gpa));
322	      return fail(msg);
323	    }
324	  }
325	
326	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
327	  // or the sole cycle-accurate engine (reusing the F8 selector).
328	  Discovery disc = discover_engines();
329	  const EngineDescriptor* acc =
330	      resolve_accurate_engine(disc.engines, cli.engine, err);
331	  if (!acc) {
332	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
333	    for (const std::string& w : disc.warnings)
334	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
335	    return 2;
336	  }
337	
338	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
339	  // cannot share architectural state with the rv64 fast leg).
340	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
341	
342	  Plan plan;
343	  plan.elf = elf_path;
344	  plan.mem_size = mem;
345	  Step qemu_step{"qemu64", "fast-leg", trig};
346	  Step vsim_step{acc->id, "accurate-leg", trig};
347	  vsim_step.extra_args = std::move(vsim_extras);  // kanata, validated
348	  plan.steps = {qemu_step, vsim_step};
349	
350	  // Banner to stderr so the window-cycle result stands alone on stdout.
351	  // vlen is the synced value the fast leg inherits from the engine.
352	  std::fprintf(stderr,
353	               "[andesim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s\n",
354	               acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
355	               elf.stem().string().c_str());
356	
357	  const PlanResult r = run_plan(plan, disc.engines);
358	  if (!r.ok()) {
359	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
360	    return 1;
361	  }
362	  // Relay each leg's stdout verbatim: the program's own prints (QEMU1 phase-1
363	  // output, then anything the ROI wrote on vsim) belong to the user.
364	  for (const PhaseResult& p : r.phases)
365	    if (!p.out.empty()) std::fwrite(p.out.data(), 1, p.out.size(), stdout);
366	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
367	  // vsim mcycle delta.
368	  {
369	    const unsigned long long q_mc = r.phases[0].mcycle;
370	    const unsigned long long v_mc = r.phases[1].mcycle;
371	    std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
372	                trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
373	  }
374	
375	  // --verify (verify_oracle F4, default off): re-run the ELF on pure QEMU
376	  // with the plugin draining at the ROI exit boundary, sampling at vsim's
377	  // halt pc, and diff the two drains in-process. The oracle plan gets its
378	  // own fresh mmap: reusing the main run's would boot the oracle on the
379	  // hybrid run's leftover memory. Its stdout is dropped -- the program's
380	  // output was already relayed from the main run.
381	  if (cli.verify) {
382	    char pcbuf[32];
383	    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
384	                  static_cast<unsigned long long>(r.phases[1].st.pc));
385	    Trigger vtrig;
386	    vtrig.kind = "verify-" + trig.kind;
387	    if (trig.kind == "pc") vtrig.params["exit_pc"] = trig.params.at("exit_pc");
388	    vtrig.params["drain_pc"] = pcbuf;
389	
390	    Plan vplan;
391	    vplan.elf = elf_path;
392	    vplan.mem_size = mem;
393	    vplan.steps = {Step{"qemu64", "fast-leg", vtrig}};
394	
395	    std::fprintf(stderr,
396	                 "[andesim] verify: oracle leg (pure QEMU drains at the ROI "
397	                 "exit, pc=%s)\n",
398	                 pcbuf);
399	    const PlanResult vr = run_plan(vplan, disc.engines);
400	    if (!vr.ok()) {
401	      std::fprintf(stderr, "andesim run --verify: %s\n", vr.error.c_str());
402	      return 1;
403	    }
404	    const DiffReport d = diff_states(vr.phases[0].st, r.phases[1].st);
405	    print_diff_report(d);
406	    if (!d.ok()) {
407	      std::fprintf(stderr,
408	                   "andesim run --verify: vsim drain diverges from the "
409	                   "QEMU oracle\n");
410	      return 1;
411	    }
412	    std::printf("[verify] PASS: vsim drain matches the QEMU oracle\n");
413	  }
414	
415	  std::printf("PASS: --mode hybrid --trigger %s (%s)\n", trig.kind.c_str(),
416	              elf.stem().string().c_str());
417	  return 0;
418	}
419	
420	}  // namespace
421	
422	int cmd_run(const Cli& cli) {
423	  if (cli.model.empty()) {
424	    std::fprintf(stderr,
425	                 "andesim run: --mode fast|cycle|hybrid is required "
426	                 "(pick the composition; see 'andesim run --help')\n");
427	    return 2;
428	  }
429	  if (!find_model(cli.model)) {
430	    std::fprintf(stderr,
431	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
432	                 cli.model.c_str());
433	    return 2;
434	  }
435	  if (!cli.gdb_port.empty() && !cli.gdb) {
436	    std::fprintf(stderr, "andesim run: --gdb-port requires --gdb\n");
437	    return 2;
438	  }
439	  // --gdb is an interactive debugging aid; the hybrid handoff runs QEMU1 then
440	  // vsim sequentially in a pipeline and cannot pause for a debugger to attach.
441	  if (cli.gdb && cli.model == "hybrid") {
442	    std::fprintf(stderr,
443	                 "andesim run: --gdb is not supported with --mode hybrid\n");
444	    return 2;
445	  }
446	  // --verify re-runs the workload against a QEMU oracle -- only the hybrid
447	  // composition has a second engine to check.
448	  if (cli.verify && cli.model != "hybrid") {
449	    std::fprintf(stderr,
450	                 "andesim run: --verify requires --mode hybrid (the %s "
451	                 "model has nothing to cross-check)\n",
452	                 cli.model.c_str());
453	    return 2;
454	  }
455	  // --trigger / --pc-start / --pc-end delimit the hybrid ROI window; fast and
456	  // cycle run the whole program and would silently drop them, handing back a
457	  // whole-program figure for the window the user asked for. Reject instead.
458	  if (!cli.trigger.empty() && cli.model != "hybrid") {
459	    std::fprintf(stderr,
460	                 "andesim run: --trigger applies only to --mode hybrid "
461	                 "(the ROI delimiter); fast/cycle run the whole program\n");
462	    return 2;
463	  }
464	  if (!cli.pc_end.empty() && cli.model != "hybrid") {
465	    std::fprintf(stderr,
466	                 "andesim run: --pc-end applies only to --mode hybrid "
467	                 "--trigger pc\n");
468	    return 2;
469	  }
470	  if (!cli.pc_start.empty() && cli.model != "hybrid") {
471	    std::fprintf(stderr,
472	                 "andesim run: --pc-start applies only to --mode hybrid "
473	                 "--trigger pc\n");
474	    return 2;
475	  }
476	  if (cli.model == "fast") return run_fast(cli);
477	  if (cli.model == "cycle") return run_accurate(cli);
478	  return run_hybrid(cli);  // model validated above; only hybrid remains
479	}
480	
481	}  // namespace andes_sim
